content.text:
I found one root cause: `ts-travel2-service` has slow database calls, and the slowdown reaches users through route-plan and travel-plan. I didn't find a second independent fault.

```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE 'SELECT%' GROUP BY 1 UNION ALL SELECT span_name, count(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name LIKE 'SELECT%' GROUP BY 1", "claim": "travel2 'SELECT travel2.entity.Trip' p95 rose from about 1.3 ms to about 420 ms, with call counts similar."},
        {"kind": "trace", "sql": "SELECT 'abn' src, span_name, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='Transaction.commit' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), approx_quantile(duration/1e6,0.95) FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name='Transaction.commit' GROUP BY 1,2", "claim": "travel2 Transaction.commit p95 rose from about 0.27 ms to about 1,112 ms."},
        {"kind": "metric", "sql": "SELECT 'abn' src, metric, avg(value) v FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2 UNION ALL SELECT 'norm', metric, avg(value) FROM normal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2", "claim": "travel2 container CPU and memory stayed flat or lower, so the slowdown is not resource saturation of the container."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name AND c.service_name IN ('ts-travel2-service') GROUP BY 1,2,3 ORDER BY 4 DESC LIMIT 20", "claim": "route-plan's calls to travel2 trips/left and trips/routes take about 2 s and 1.3 s at p95, matching travel2's latency."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name AND c.service_name IN ('ts-route-plan-service') GROUP BY 1,2,3 ORDER BY 4 DESC LIMIT 20", "claim": "travel-plan's calls to route-plan cheapestRoute and quickestRoute take about 5.5 s and 1.3 s at p95, matching route-plan's latency."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name AND c.service_name IN ('ts-travel-plan-service') GROUP BY 1,2,3 ORDER BY 4 DESC LIMIT 20", "claim": "ui-dashboard's calls to travel-plan cheapest, quickest and minStation take about 5.5 s, 1.3 s and 1.9 s at p95."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p.service_name caller, c.service_name callee, c.span_name, count(*) n, approx_quantile(c.duration/1e6,0.95) callee_p95_ms, approx_quantile(p.duration/1e6,0.95) caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.service_name<>c.service_name AND c.service_name IN ('ts-travel2-service') GROUP BY 1,2,3 ORDER BY 4 DESC LIMIT 20", "claim": "ui-dashboard's direct calls to travel2 trips/left take about 1.1 s at p95, matching travel2's latency."}]}
  ]
}
```

